use atlas_native_storage_contract::{create_workspace,add_file};use std::{fs,path::PathBuf,time::{SystemTime,UNIX_EPOCH}};use rusqlite::Connection;
fn root()->PathBuf{std::env::temp_dir().join(format!("atlas-docs-{}-{}",std::process::id(),SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos()))}
fn source(p:&PathBuf,id:&str)->(String,String,String){Connection::open(p.join("atlas.sqlite3")).unwrap().query_row("SELECT o.path,o.text_status,s.body FROM objects o JOIN search_index s ON s.object_id=o.id WHERE o.id=?",[id],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).unwrap()}
fn hit(p:&PathBuf,id:&str,word:&str)->i64{Connection::open(p.join("atlas.sqlite3")).unwrap().query_row("SELECT count(*) FROM search_chunks WHERE object_id=? AND search_chunks MATCH ?",[id,word],|r|r.get(0)).unwrap()}
#[test]fn pdf_extracts_two_pages_in_order(){let p=root();create_workspace(&p).unwrap();let bytes=fs::read("/private/tmp/atlas-native-storage/testdata/two-pages.pdf").unwrap();let id=add_file(&p,"pages.pdf",&bytes).unwrap();let(path,status,text)=source(&p,&id);assert_eq!(fs::read(p.join(path)).unwrap(),bytes);assert_eq!(status,"available");assert!(text.contains("first page"));assert!(text.contains("second page"));assert!(text.find("first page")<text.find("second page"));assert!(text.contains("page\n"),"pages must not be concatenated without a separator");assert!(hit(&p,&id,"first")>0&&hit(&p,&id,"second")>0);fs::remove_dir_all(p).unwrap();}
#[test]fn docx_extracts_paragraph_and_table(){let p=root();create_workspace(&p).unwrap();let bytes=fs::read("/private/tmp/atlas-native-storage/testdata/table.docx").unwrap();let id=add_file(&p,"table.docx",&bytes).unwrap();let(path,status,text)=source(&p,&id);assert_eq!(fs::read(p.join(path)).unwrap(),bytes);assert_eq!(status,"available");assert!(text.contains("paragraphunique"));assert!(text.contains("tableunique"));assert!(hit(&p,&id,"paragraphunique")>0&&hit(&p,&id,"tableunique")>0);fs::remove_dir_all(p).unwrap();}
#[test]fn corrupt_documents_preserve_bytes_and_report_unavailable(){let p=root();create_workspace(&p).unwrap();for name in ["bad.pdf","bad.docx"]{let bytes=b"broken document";let id=add_file(&p,name,bytes).unwrap();let(path,status,text)=source(&p,&id);assert_eq!(fs::read(p.join(path)).unwrap(),bytes);assert_eq!(status,"unavailable");assert!(text.is_empty());}fs::remove_dir_all(p).unwrap();}
